import type { Recipe } from "../types";

type IngredientDraft = [name: string, amount: string, note?: string, scaleWithBatch?: boolean];
type StepDraft = [title: string, detail: string, why: string, tip?: string];
type Draft = Omit<Recipe, "ingredients" | "steps"> & { ingredients: IngredientDraft[]; steps: StepDraft[] };
const make = (draft: Draft): Recipe => ({
  ...draft,
  reviewedOn: "2026-10-24",
  ingredients: draft.ingredients.map(([name, amount, note, scaleWithBatch], index) => ({ id: `${draft.id}-i${index + 1}`, name, amount, ...(note ? { note } : {}), ...(scaleWithBatch === false ? { scaleWithBatch: false } : {}) })),
  steps: draft.steps.map(([title, detail, why, tip], index) => ({ id: `${draft.id}-s${index + 1}`, title, detail, why, ...(tip ? { tip } : {}) })),
});
const source = (title: string, url: string) => ({ title, url });
const ka = (slug: string, title: string) => source(`King Arthur Baking: ${title}`, `https://www.kingarthurbaking.com/recipes/${slug}-recipe`);
const coldStorage = "Keep covered at 40°F / 4°C or colder. Refrigerate within 2 hours of preparation or serving (1 hour above 90°F / 32°C).";
const editorial = "Editorial recipe and technique review; this version has not been kitchen tested. Oven times are starting ranges: use the stated doneness cues.";

function laminated(chocolate: boolean): Recipe {
  const id = chocolate ? "pain-au-chocolat" : "croissants";
  return make({
    id, category: null, title: chocolate ? "Pain au Chocolat" : "Croissants", difficulty: "Challenges",
    blurb: chocolate ? "Chocolate-filled croissant dough, with every lamination turn and rest specified." : "A two-day, butter-laminated dough with measured turns, cool proofing, and a full bake.",
    time: "18–24 hr over 2 days; about 2 hr active", yield: chocolate ? "12 chocolate pastries" : "12 croissants",
    equipment: ["Digital scale", "Ruler and rolling pin", "Two baking sheets", "Parchment", "Thermometer", "Cool work surface"],
    ingredients: [["Unbleached all-purpose flour", "500 g", "Dough; a moderately strong flour, about 11–12% protein"], ["Instant yeast", "7 g", "Dough; not an interchangeable volume of fresh yeast"], ["Granulated sugar", "50 g", "Dough"], ["Fine salt", "10 g", "Dough"], ["Whole milk", "280 ml", "Dough; cold"], ["Unsalted butter", "40 g", "Dough; softened"], ["Unsalted butter", "250 g", "Lamination block; preferably 82% fat"], ["Large egg", "1", "Egg wash"], ["Water", "15 ml", "Egg wash"], ...(chocolate ? [["Semisweet baking chocolate", "180 g", "Filling; divide into 24 thin batons"] as IngredientDraft] : [])],
    steps: [
      ["Day 1: mix the dough", "Mix flour, yeast, sugar, and salt, then add milk and the dough butter. Knead 4–6 minutes until smooth but not as elastic as sandwich bread. Cover and rest 30 minutes at about 70°F / 21°C.", "Some gluten provides strength; excessive development makes the dough resist rolling."],
      ["Refrigerate overnight", "Flatten dough to an 8-inch / 20 cm square, wrap with room for modest expansion, and refrigerate 8–12 hours at 40°F / 4°C or colder.", "The long cool rest develops flavor and relaxes the dough before lamination."],
      ["Make the butter block", "Between parchment sheets, tap and roll the lamination butter to a 6-inch / 15 cm square. Refrigerate, then briefly temper until it bends without cracking and remains cool, about 55–60°F / 13–16°C.", "Butter that is brittle breaks into chunks; warm butter smears into dough instead of forming sheets."],
      ["Enclose the butter", "Roll the cold dough into a 9-inch / 23 cm square. Set butter diagonally in the center. Fold the dough corners over it like an envelope, pinch seams closed, and keep flour off the inside of the seams.", "A sealed envelope prevents exposed butter escaping during rolling."],
      ["Make the first turn", "With light flour, roll the packet to roughly 8 × 24 inches / 20 × 60 cm. Brush away excess flour. Fold the bottom third up and top third down, like a letter. Wrap and refrigerate 45–60 minutes.", "A letter fold multiplies the butter layers. Rest prevents elastic dough snapping back."],
      ["Repeat two turns", "Turn the packet 90 degrees, roll to the same rectangle, and letter-fold again. Chill 45–60 minutes. Repeat once more for three letter folds total, then chill 60 minutes. If butter smears or dough tears at any point, stop and chill 20–30 minutes before continuing.", "Three controlled turns build flake without making the butter layers too fragile."],
      ["Roll and cut", chocolate ? "Roll to a 12 × 18-inch / 30 × 46 cm rectangle, about 1/4 inch / 6 mm thick. Trim edges lightly. Cut into 12 rectangles about 3 × 6 inches. If dough resists, cover and refrigerate 15–20 minutes before continuing." : "Roll to a 12 × 18-inch / 30 × 46 cm rectangle, about 1/4 inch / 6 mm thick. Trim edges lightly. Cut into six 3 × 12-inch rectangles; cut each diagonally to make 12 long triangles. Rest cold for 15–20 minutes if the dough contracts.", "Even thickness gives consistent rise, while a sharp straight cut leaves the laminated edges open."],
      ["Shape", chocolate ? "Place a chocolate baton near one 3-inch end of each rectangle. Fold dough over it, add a second baton, and roll the remaining dough around both. Put seam down on parchment-lined sheets, leaving 3 inches between pastries." : "Gently stretch each triangle lengthwise. Starting at its wide base, roll loosely toward its tip without squeezing the layers. Place tip underneath on parchment-lined sheets, leaving 3 inches between croissants.", "A bottom seam anchors the shape, and a relaxed roll leaves room for expansion."],
      ["Proof gently", "Cover loosely and proof at 72–77°F / 22–25°C for 2–4 hours, until very puffy, layers separate visibly, and pastries wobble when the tray moves. Avoid temperatures above 80°F / 27°C. Proof by appearance rather than the clock; chilled dough may take longer.", "Too much warmth melts butter; underproofed centers bake dense and can leak butter."],
      ["Glaze and bake", "Heat a conventional oven to 400°F / 205°C. Beat egg with the egg-wash water. Brush tops gently, avoiding cut edges. Bake one tray at a time for 10 minutes; reduce to 375°F / 190°C and bake another 12–18 minutes until deeply golden, crisp, and browned underneath.", "Initial heat creates lift; the lower finishing temperature dries the centers before the tops burn."],
      ["Cool before opening", "Transfer pastries to a rack and cool at least 20–30 minutes. A cut pastry should show a cooked, open interior with no gummy dough band. If the outside colors too fast, tent loosely with foil while it finishes.", "Warm laminated dough continues to set after leaving the oven."],
    ],
    storage: "Best the day baked. Keep airtight at room temperature up to 2 days or freeze up to 1 month. Recrisp thawed pastries at 325°F / 165°C for 6–10 minutes, then cool briefly.",
    notes: [editorial, "Contains wheat, milk, and eggs; chocolate may contain soy. Scaling requires more sheets and repeated batches of the same thickness, not thicker dough. Coconut oil does not behave like a butter block."],
    reviewNotes: ["Replaced cup-based, underspecified dough with weighed flour, liquid, and butter; specified three turns, dimensions, overnight rest, proof endpoints, wash, bake range, and cooling."],
    sources: [ka(chocolate ? "pain-au-chocolat" : "bakers-croissants", chocolate ? "Pain au chocolat shaping and staged rests" : "Croissant lamination and temperature control")],
  });
}

function layeredPuff(glazed: boolean): Recipe {
  const id = glazed ? "napoleons" : "mille-feuille";
  return make({
    id, category: null, title: glazed ? "Napoleons" : "Mille-Feuille", difficulty: "Challenges",
    blurb: glazed ? "Eight vanilla custard pastries with a defined white glaze and feathered chocolate finish." : "Crisp puff pastry and fully cooked vanilla custard, assembled in individual portions.",
    time: "4 hr 30 min including custard chilling", yield: "8 three-layer pastries",
    equipment: ["Two flat baking sheets", "Parchment", "Rolling pin", "Saucepan and whisk", "Fine sieve", "Serrated knife", "Piping bag"],
    ingredients: [["All-butter puff pastry", "500 g", "Thawed in the refrigerator; purchased pastry is intentional"], ["Whole milk", "500 ml", "Custard"], ["Large egg yolks", "4", "Custard"], ["Granulated sugar", "100 g", "Custard"], ["Cornstarch", "40 g", "Custard; provides sliceable support"], ["Fine salt", "1/4 tsp", "Custard"], ["Unsalted butter", "30 g", "Custard"], ["Vanilla extract", "2 tsp", "Custard"], ...(glazed ? [["Confectioners' sugar", "150 g", "Glaze; sifted"], ["Milk", "25 ml", "Glaze; add gradually"], ["Semisweet chocolate", "25 g", "Glaze stripes; melted"]] as IngredientDraft[] : [["Confectioners' sugar", "15 g", "Dusting"]] as IngredientDraft[])],
    steps: [
      ["Start the custard", "Heat milk just to steaming with small edge bubbles. Separately whisk yolks, sugar, cornstarch, and salt until smooth. Gradually whisk in about half the hot milk, then return everything to the saucepan.", "Tempering reduces curdling; dispersing the starch first prevents lumps."],
      ["Cook and chill custard", "Whisk over medium heat until thick bubbles break in the center, then cook and whisk 1 additional minute, about 190–200°F / 88–93°C. Remove, strain, and stir in butter and vanilla. Spread in a shallow dish, cover the surface, and refrigerate until cold, at least 3 hours.", "The starch needs a brief boil, and fully cold custard supports the pastry layers."],
      ["Roll and dock", "Roll puff pastry to about 12 × 16 inches / 30 × 40 cm and 1/8 inch / 3 mm thick, working in smaller pieces if necessary. Transfer to parchment on a flat sheet. Prick all over with a fork and refrigerate 30 minutes. Heat oven to 375°F / 190°C.", "Docking, chilling, and a thin even sheet limit uneven balloons and shrinkage."],
      ["Bake flat", "Cover pastry with another sheet of parchment and the second baking sheet. Bake 25 minutes, then carefully remove the upper sheet and parchment. Bake 12–20 minutes more until deep golden throughout, including the underside; allow more time if the middle remains pale.", "The upper sheet controls expansion, while uncovered baking removes moisture."],
      ["Cool and portion", "Cool completely on a rack, about 30 minutes. Using a serrated knife and a gentle sawing motion, trim the pastry and cut 24 matching rectangles, roughly 1 1/2 × 4 inches / 4 × 10 cm. Reserve the neatest 8 for tops.", "Precut pieces avoid crushing a large assembled stack when portioning."],
      ["Finish the tops", glazed ? "Stir the glaze milk gradually into confectioners' sugar to make a thick spreadable icing; use only as much as needed. Spread on the 8 reserved tops. Pipe thin parallel lines of melted chocolate; immediately drag a toothpick across alternating directions. Let set about 15 minutes." : "Dust the 8 reserved top pieces lightly with confectioners' sugar just before assembly. Keep the other pieces bare.", "Finishing tops before stacking protects the fragile cream-filled layers."],
      ["Fill", "Whisk the cold custard briefly until smooth. Divide it over 16 pastry rectangles using a piping bag or spoon, leaving a small border. Place one filled piece over another to make each portion, then add a finished top.", "Uniform filling prevents the pastries leaning; overfilling squeezes custard out."],
      ["Set briefly and serve", "Refrigerate the assembled pastries for 20–30 minutes, then serve the same day. Keep them chilled until serving.", "A brief chill steadies the filling; long storage gradually softens puff pastry."],
    ],
    storage: `${coldStorage} Best the day assembled; refrigerate leftovers up to 2 days. Custard can be made 2 days ahead; keep unfilled baked pastry airtight at room temperature for 1 day.`,
    notes: [editorial, "Contains wheat, milk, and eggs. A pure pastry-cream filling is used; optional whipped cream was removed to avoid weakening the layer support."],
    reviewNotes: ["Specified pastry weight, complete custard formula, weighted baking, doneness, and 24 matching pieces; replaced undefined optional finishes with one complete finish."],
    sources: glazed ? [ka("napoleons", "Weighted puff baking and feathered glaze")] : [source("RecipeTin Eats: Mille-feuille technique and assembly", "https://www.recipetineats.com/mille-feuille-recipe/"), ka("pastry-cream-creme-patissiere", "Custard cooking endpoint")],
  });
}

